(() => {
'use strict';
const $=id=>document.getElementById(id);let tab='map',item='potion',dialogue=null;const keeper=new Image();let keeperRects=[];
const g=()=>window.gameDebug;
const classes=['Следопыт','Маг','Защитник'];
function button(label,fn){const b=document.createElement('button');b.textContent=label;b.onclick=fn;return b}
function switchTab(next){tab=next;for(const name of['map','hero','bag']){$(name+'-view').hidden=name!==tab;$('tab-'+name).classList.toggle('active',name===tab);$('tab-'+name).setAttribute('aria-selected',String(name===tab))}if(tab!=='map')$('title').textContent='Часовня';else g().render();renderViews()}
function selectHero(step){if(g().busy)return;const s=g().state,alive=s.party.filter(p=>p.hp>0);if(!alive.length)return;const i=alive.findIndex(p=>p.id===s.active);s.active=alive[(i+step+alive.length)%alive.length].id;g().save();g().render()}
function paintHero(){const s=g().state,a=g().active();$('hero-name').textContent=a.name;$('hero-class').textContent=classes[a.kind];$('hero-level').textContent='Уровень '+s.level;$('hero-art').replaceChildren(g().art(a.kind*4));const threshold=s.level*100,percent=Math.min(100,s.xp/threshold*100);$('hero-progress').innerHTML='<div><span>Опыт</span><div class="hp-track"><i style="width:'+percent+'%"></i></div><b>'+s.xp+' / '+threshold+'</b></div><div><span>Здоровье</span><div class="hp-track"><i style="width:'+a.hp/a.max*100+'%"></i></div><b>'+a.hp+' / '+a.max+'</b></div>';
const values=a.kind===0?[2,4,1]:a.kind===1?[-1,2,4]:[4,1,1];$('hero-stats').innerHTML=values.map((v,i)=>'<div><span>'+['✊','➶','▤'][i]+'</span><small>'+['Сила','Ловкость','Мудрость'][i]+'</small><b>'+(v>=0?'+':'')+v+'</b></div>').join('');$('equipment').replaceChildren();if(a.kind===0){for(const weapon of[{id:'bow',label:'Лук',icon:'🏹',range:5,damage:6},{id:'sword',label:'Короткий меч',icon:'⚔',range:1,damage:8}]){const b=button('',()=>{a.weapon=weapon.id;a.range=weapon.range;a.damage=weapon.damage;g().save();g().render()});b.innerHTML='<span>'+weapon.icon+'</span><b>'+weapon.label+'</b><small>'+weapon.range+' кл. · d'+weapon.damage+' +2</small>';b.className='gear '+((a.weapon||'sword')===weapon.id?'equipped':'');b.disabled=g().busy;$('equipment').append(b)}}else{const b=document.createElement('div');b.className='gear equipped';b.innerHTML='<span>'+(a.kind===1?'✧':'⚔')+'</span><b>'+(a.kind===1?'Посох · луч':'Меч и щит')+'</b><small>'+a.range+' кл. · d'+a.damage+' +2</small>';$('equipment').append(b)}
$('level-up').textContent=s.xp>=threshold?'⇧ Повысить уровень':'⇧ Повысить уровень · ещё '+(threshold-s.xp)+' опыта';$('level-up').disabled=s.xp<threshold||g().busy||s.combat;$('hero-action-note').textContent=s.combat?'В бою повышение уровня недоступно. Сменить оружие можно перед атакой.':'При повышении уровня отряд получает +4 к максимальному здоровью.'}
function levelUp(){const s=g().state;if(s.combat||s.xp<s.level*100||g().busy)return;s.xp-=s.level*100;s.level++;for(const a of s.party){a.max+=4;if(a.hp>0)a.hp=a.max}g().tell('Отряд достиг уровня '+s.level+'. Максимальное здоровье каждого героя увеличено на 4.');g().render()}
function items(){const s=g().state;return[{id:'potion',name:'Лечебное зелье',icon:'⚗',amount:s.potions,category:'Расходуемое',description:'Восстанавливает до 10 HP выбранному герою. В бою расходует его действие.'},{id:'coins',name:'Монеты',icon:'◉',amount:s.gold,category:'Валюта',description:'Найденные в часовне монеты. Сохраняются вместе с прогрессом отряда.'},...(s.chest?[{id:'letter',name:'Письмо',icon:'▤',amount:1,category:'Зацепка',description:'«Колокол увезли на север. Не верьте настоятелю». Слова подтверждают след, о котором говорит хранительница.'}]:[]),...(s.relic?[{id:'relic',name:'Язычок колокола',icon:'♮',amount:1,category:'Реликвия',description:'Серебряный язычок исчезнувшего колокола. Найден на алтаре часовни. Связан с её хранительницей Эллен.'}]:[])]}
function paintBag(){const list=items(),selected=list.find(i=>i.id===item)||list[0];item=selected.id;$('bag-gold').textContent=g().state.gold+' монет';$('bag-items').replaceChildren();for(const it of list){const b=button('',()=>{item=it.id;paintBag()});b.className='bag-item '+(item===it.id?'selected':'');b.innerHTML='<span>'+it.icon+'</span><b>'+it.name+'</b><small>×'+it.amount+'</small>';$('bag-items').append(b)}$('item-detail').innerHTML='<span class="item-category">'+selected.category+'</span><div class="item-icon">'+selected.icon+'</div><h2>'+selected.name+'</h2><p>'+selected.description+'</p><div id="item-actions" class="options"></div>';if(selected.id==='potion'){const b=button('Выпить · '+g().active().name,()=>g().potion());b.disabled=$('potion').disabled;$('item-actions').append(b);if(g().active().hp>=g().active().max){const p=document.createElement('p');p.className='subtle';p.textContent='У выбранного героя полное здоровье.';$('item-detail').append(p)}}if(['letter','relic'].includes(selected.id))$('item-actions').append(button('Открыть хронику',()=>g().journal()))}
function renderViews(){if(!g())return;if(tab==='hero'){paintHero();$('title').textContent='Часовня'}if(tab==='bag'){paintBag();$('title').textContent='Часовня'}if(dialogue)paintDialogue()}
function drawKeeper(c,mode='portrait'){const miniature=mode==='prop';c.width=miniature?96:256;c.height=miniature?120:320;const cx=c.getContext('2d');cx.clearRect(0,0,c.width,c.height);cx.setTransform(miniature?.375:1,0,0,miniature?.375:1,0,0);const r=keeperRects[mode==='portrait'?0:1];if(!r)return;const scale=mode==='prop'?Math.min(184/r.w,250/r.h):Math.min(230/r.w,305/r.h),w=r.w*scale,h=r.h*scale;cx.drawImage(keeper,r.sx,r.sy,r.w,r.h,128-w/2,mode==='prop'?320/1.45-h*.81:160-h/2,w,h)}
function keeperCanvas(){const c=document.createElement('canvas');c.className='sprite';drawKeeper(c);return c}
function dialogueLine(text,options,name='Эллен · хранительница',portrait=true){dialogue={text,options,name,portrait};paintDialogue()}
function paintDialogue(){if(!dialogue)return;$('dialogue').hidden=false;$('speaker-name').textContent=dialogue.name;$('dialogue-text').textContent=dialogue.text;$('speaker-art').replaceChildren();if(dialogue.portrait)$('speaker-art').append(keeperCanvas());else{const mark=document.createElement('span');mark.className='narrator-mark';mark.textContent='◇';$('speaker-art').append(mark)}$('dialogue-options').replaceChildren();for(const option of dialogue.options)$('dialogue-options').append(button('▣  '+option.label,option.fn))}
function closeDialogue(){dialogue=null;$('dialogue').hidden=true}
function recordReply(question,response){g().tell('Вы: «'+question+'» Эллен: «'+response+'»');g().render();dialogueLine(response,[{label:'Задать другой вопрос',fn:openKeeper},{label:'Закончить разговор',fn:closeDialogue}])}
function openKeeper(){if(g().state.combat)return;switchTab('map');dialogueLine('Колокол забрали на север. Я видела людей, которые его увезли. Что вы хотите узнать?',[
{label:'Кто это сделал?',fn:()=>{const s=g().state;s.clues=s.clues||[];if(!s.clues.includes('courier'))s.clues.push('courier');recordReply('Кто это сделал?','Люди настоятеля. Они забрали колокол по его приказу и ушли через северную дорогу. В сундуке осталось письмо с предупреждением.')}},
{label:'Что находится на севере?',fn:()=>recordReply('Что находится на севере?','Старая дорога ведёт к закрытому монастырю. Серебряный язычок с алтаря докажет, что вы были в этой часовне.')},
{label:'Попросить довериться · убеждение d20',fn:persuade},
{label:'У меня нет времени',fn:()=>{g().tell('Вы прервали разговор с Эллен. К её вопросам можно вернуться позже.');g().render();closeDialogue()}}]);}
function persuade(){const s=g().state;if(s.persuasionAttempted){dialogueLine(s.secretKnown?'Я уже сказала вам о тайнике за книгами. Больше мне добавить нечего.':'Я пока не готова доверять вам больше. Но основные ответы я уже дала.',[{label:'Другой вопрос',fn:openKeeper},{label:'Закончить',fn:closeDialogue}]);return}const n=g().roll(),bonus=[0,2,1][g().active().kind],ok=n+bonus>=12;s.persuasionAttempted=true;s.secretKnown=ok;if(ok)s.xp+=10;const response=ok?'Я доверюсь вам. За книгами у настоятеля спрятан список имён. Найдите его, когда доберётесь до монастыря.':'Простите. Я слишком мало вас знаю, чтобы рисковать чужими жизнями.';g().tell('Убеждение: d20 '+n+' + '+bonus+' против 12 — '+(ok?'успех. +10 опыта.':'неудача.')+' Эллен: «'+response+'»');g().render();dialogueLine('d20 '+n+' + '+bonus+' против 12. '+response,[{label:'Вернуться к вопросам',fn:openKeeper},{label:'Закончить разговор',fn:closeDialogue}])}
function openNarrator(){switchTab('map');if(!g().state.combat&&!g().state.complete){dialogueLine('Хранительница вышла из укрытия. Подойдите к ней у северного алтаря: она знает, кто забрал колокол.',[{label:'Показать хранительницу',fn:()=>{closeDialogue();g().select({x:5,y:1})}},{label:'Что делать дальше?',fn:()=>dialogueLine('Заберите реликвию с алтаря и проверьте сундук. Для взаимодействия встаньте в соседнюю клетку.',[{label:'Продолжить',fn:closeDialogue}],'Ведущий',false)},{label:'Хроника',fn:()=>g().journal()}],'Ведущий',false);return}if(g().state.complete){openKeeper();return}dialogueLine(g().state.logs.at(-1),[{label:'Наша цель?',fn:()=>dialogueLine('Победите двух стражей, затем исследуйте сундук и алтарь. За закрытой дверью часовни скрывается след исчезнувшего колокола.',[{label:'Вернуться к бою',fn:closeDialogue}],'Ведущий',false)},{label:'Как играть?',fn:()=>g().help()},{label:'Продолжить бой',fn:closeDialogue}],'Ведущий',false)}
window.initViews=()=>{for(const name of['map','hero','bag'])$('tab-'+name).onclick=()=>switchTab(name);$('hero-prev').onclick=()=>selectHero(-1);$('hero-next').onclick=()=>selectHero(1);$('level-up').onclick=levelUp;$('dialogue-close').onclick=closeDialogue;renderViews()};
window.renderViews=renderViews;window.drawKeeper=drawKeeper;window.openKeeperDialogue=openKeeper;window.openNarratorDialogue=openNarrator;window.closeDialogue=closeDialogue;
keeper.onload=()=>{const c=document.createElement('canvas');c.width=keeper.width;c.height=keeper.height;const cx=c.getContext('2d',{willReadFrequently:true});cx.drawImage(keeper,0,0);keeperRects=[];for(let i=0;i<2;i++){const sx=i*keeper.width/2,w=Math.floor(keeper.width/2),h=keeper.height,a=cx.getImageData(sx,0,w,h).data;let l=w,t=h,r=0,b=0;for(let y=0;y<h;y++)for(let x=0;x<w;x++)if(a[(y*w+x)*4+3]>40){l=Math.min(l,x);t=Math.min(t,y);r=Math.max(r,x);b=Math.max(b,y)}keeperRects.push({sx:sx+l,sy:t,w:r-l+1,h:b-t+1})}g()?.render()};keeper.src='assets/keeper.png';
window.viewsDebug={switchTab,openKeeper,openNarrator,persuade,levelUp,get tab(){return tab}};
})();
